package tw.tsm.gamelogic.systems

import io.github.oshai.kotlinlogging.KotlinLogging
import tw.tsm.domain.data.EveMinePlacement
import tw.tsm.domain.data.SceneEveData
import tw.tsm.domain.interfaces.GameSession
import java.util.concurrent.ConcurrentHashMap
import kotlin.math.abs
import kotlin.math.min

private val mineLogger = KotlinLogging.logger {}

/**
 * Server-side Mine encounter system.
 *
 * DVT client EventManager.lua defines EEventTrigger.Mine=7 and explicitly says
 * the trigger is now generated by the server. Eve.emg stores the affected
 * region and Eve event IDs in MineData.
 *
 * Exact original server RNG is not present in Lua/File.dat. Therefore this
 * class deliberately isolates pacing from Eve semantics: an encounter attempt
 * happens after meaningful movement in a MineData region, while the actual
 * event/fight is always taken from Eve.emg.
 */
class MineEncounterSystem(
    private val eveData: Map<Int, SceneEveData>,
    private val stateMachine: EveEventStateMachine,
    private val triggerRouter: EveTriggerRouter,
    private val playerStateManager: PlayerStateManager,
    private val nowMs: () -> Long = { System.currentTimeMillis() }
) {
    private val states = ConcurrentHashMap<Long, MineWalkState>()

    suspend fun onPlayerMove(
        session: GameSession,
        oldX: Int,
        oldY: Int,
        newX: Int,
        newY: Int
    ) {
        if (session.roleId <= 0 || session.battleId != 0L || !session.loginFinished) return
        val charId = session.roleId.toLong()
        if (stateMachine.getSession(charId) != null) return

        val now = nowMs()
        val noEncounterUntil = playerStateManager.getState(charId)?.noEncounterUntil ?: 0L
        if (now < noEncounterUntil) {
            // ItemUse_4 của DVT là "không gặp địch 20 giây". Không tích lũy
            // quãng đường trong thời gian này để tránh hết buff là gặp ngay.
            states[charId]?.distancePx = 0
            return
        }

        val scene = eveData[session.mapId] ?: return
        if (scene.mines.isEmpty()) return

        val mine = selectMine(scene, newX, newY)
        if (mine == null || mine.events.isEmpty()) {
            states.remove(charId)
            return
        }

        val state = states.compute(charId) { _, previous ->
            when {
                previous == null ->
                    MineWalkState(mapId = session.mapId, mineId = mine.id)
                previous.mapId != session.mapId || previous.mineId != mine.id ->
                    // Cooldown là theo người chơi, không phải theo MineData. Giữ cooldown
                    // khi đổi vùng để không thể gặp liên tiếp chỉ vì bước qua biên mine.
                    previous.copy(
                        mapId = session.mapId,
                        mineId = mine.id,
                        distancePx = 0
                    )
                else -> previous
            }
        } ?: return

        // Cooldown là thời gian nghỉ thực sự: di chuyển trong khoảng này không được
        // nạp sẵn distance budget rồi kích hoạt ngay khi timer vừa hết.
        if (now < state.cooldownUntil) return

        val moved = min(
            abs(newX - oldX) + abs(newY - oldY),
            MAX_COUNTED_MOVE_PX
        )
        if (moved <= 0) return
        state.distancePx += moved

        if (state.distancePx < DISTANCE_PER_ATTEMPT_PX) return

        state.distancePx = 0
        if (triggerRouter.triggerMine(session, mine.id)) {
            state.cooldownUntil = now + ENCOUNTER_COOLDOWN_MS
            mineLogger.info {
                "Mine encounter: map=${session.mapId} mineId=${mine.id} " +
                    "player=${session.characterName} cooldown=${ENCOUNTER_COOLDOWN_MS}ms"
            }
        }
    }

    /**
     * BattleManager gọi trước EveFlowController.resumeAfterBattle().
     *
     * Nếu trận vừa kết thúc xuất phát từ Mine trigger (triggerKind=7), bắt đầu lại
     * grace period từ thời điểm trận thực sự kết thúc. Trước đây timer chạy từ lúc
     * bắt đầu trận nên một trận kéo dài >= cooldown khiến người chơi vừa đi vài bước
     * đã gặp tiếp.
     */
    fun onBattleEnd(characterId: Long, playerWin: Boolean = true) {
        val eventSession = stateMachine.getSession(characterId) ?: return
        // The old grace only applied to Mine-triggered battles; losing the
        // map12861/Eve6/Fight28 quest battle left immediate wild encounters
        // enabled even while the client was exiting its defeat UI.
        if (DvtBattleDefeatRecoveryPolicy.needsPostDefeatMineGrace(
                eventSession.mapId, eventSession.eveNo, eventSession.fightDataKey, playerWin
            )
        ) {
            val graceUntil = nowMs() + ENCOUNTER_COOLDOWN_MS
            states.compute(characterId) { _, previous ->
                MineWalkState(
                    mapId = eventSession.mapId,
                    mineId = previous?.mineId ?: -1,
                    distancePx = 0,
                    cooldownUntil = maxOf(previous?.cooldownUntil ?: 0L, graceUntil)
                )
            }
            mineLogger.info {
                "DVT quest defeat MineData grace: charId=$characterId " +
                    "map=${eventSession.mapId} eve=${eventSession.eveNo} " +
                    "fight=${eventSession.fightDataKey} until=$graceUntil"
            }
            return
        }
        if (eventSession.triggerKind != MINE_TRIGGER_KIND) return

        states[characterId]?.let { state ->
            state.distancePx = 0
            state.cooldownUntil = nowMs() + ENCOUNTER_COOLDOWN_MS
        }
    }

    fun cleanup(characterId: Long) {
        states.remove(characterId)
    }

    companion object {
        const val MINE_TRIGGER_KIND = 7
        /**
         * Pacing fallback: exact original mobile-server RNG is not present in Lua/Eve.
         * Keep the already-established 27s interval, but enforce it as a real
         * post-encounter grace period instead of allowing battle time/mine switching
         * to consume or bypass it.
         */
        const val ENCOUNTER_COOLDOWN_MS = 27_000L

        /**
         * Ten map grids (20px each). This is pacing only; MineData event semantics
         * are not guessed or modified.
         */
        const val DISTANCE_PER_ATTEMPT_PX = 200

        /** Prevent malformed/teleport-like movement packets from instantly filling the budget. */
        private const val MAX_COUNTED_MOVE_PX = 80

        /**
         * Prefer explicit rectangles (sizeKind=0) over the map-wide MineData entry
         * (sizeKind=1). Map 12591 uses exactly this layout: two mining rectangles
         * plus one whole-map fallback.
         */
        fun selectMine(scene: SceneEveData, x: Int, y: Int): EveMinePlacement? {
            val explicit = scene.mines.values
                .asSequence()
                .filter { it.sizeKind == 0 && it.containsPixel(x, y) }
                .minByOrNull { it.gridWidth.toLong() * it.gridHeight.toLong() }
            if (explicit != null) return explicit

            return scene.mines.values
                .asSequence()
                .filter { it.sizeKind == 1 && it.containsPixel(x, y) }
                .minByOrNull { it.id }
        }
    }
}

private data class MineWalkState(
    val mapId: Int,
    val mineId: Int,
    var distancePx: Int = 0,
    var cooldownUntil: Long = 0L
)
